const input = $input.first().json;

const platform = (input.params?.platform || "instagram").toLowerCase();

let data;

if (platform === "instagram") {
  data = {
    source: "mock-metricool",
    platform: "Instagram",
    views: 18600,
    reach: 11400,
    impressions: 22100,
    engagement: 1260,
    engagementRate: 6.8,
    followers: 3420,
    followerGrowth: 126
  };
} else if (platform === "facebook") {
  data = {
    source: "mock-metricool",
    platform: "Facebook",
    views: 15200,
    reach: 9800,
    impressions: 19400,
    engagement: 940,
    engagementRate: 4.8,
    followers: 5100,
    followerGrowth: 84
  };
} else {
  return [
    {
      json: {
        success: false,
        error: "Unsupported platform"
      }
    }
  ];
}

return [
  {
    json: {
      success: true,
      ...data
    }
  }
];
